// Odoo App Store catalogue. odoo-apps.json is generated by
// scripts/sync_odoo_apps.py (`npm run sync:apps`) and only contains
// published products; product-categories.json is the curated site category
// for each technical name.
import catalogue from './odoo-apps.json';
import categoryMap from './product-categories.json';

type CatalogueProduct = (typeof catalogue.products)[number];

export interface Product extends CatalogueProduct {
  slug: string;
  url: string;
  category: string;
  priceLabel: string;
}

// Display order of the category filters and of the products page.
export const CATEGORY_ORDER = [
  'AI', 'Productivity', 'Sales', 'Accounting', 'Warehouse', 'Purchase', 'HR',
  'Manufacturing', 'Marketing', 'Website', 'Operations', 'Industry', 'Theme',
];

const categories = categoryMap as Record<string, string>;
const categoryRank = (category: string) => {
  const i = CATEGORY_ORDER.indexOf(category);
  return i === -1 ? CATEGORY_ORDER.length : i;
};

export function formatPrice(price: number): string {
  return price === 0 ? 'FREE' : `$${price.toFixed(2)}`;
}

export const products: Product[] = catalogue.products
  .map((p) => {
    const slug = p.technicalName.replaceAll('_', '-');
    return {
      ...p,
      slug,
      url: `/products/${slug}/`,
      category: categories[p.technicalName] ?? (p.kind === 'theme' ? 'Theme' : 'Productivity'),
      priceLabel: formatPrice(p.price),
    };
  })
  // By category, free before paid, then by name.
  .sort((a, b) =>
    categoryRank(a.category) - categoryRank(b.category)
    || Number(a.price > 0) - Number(b.price > 0)
    || a.name.localeCompare(b.name, 'en', { sensitivity: 'base' })
  );

const byTechnicalName = new Map(products.map((p) => [p.technicalName, p]));
if (byTechnicalName.size !== new Set(products.map((p) => p.slug)).size) {
  throw new Error('Two Odoo products map to the same page slug');
}

export function getProduct(technicalName: string): Product | undefined {
  return byTechnicalName.get(technicalName);
}

export const productCategories = [...new Set(products.map((p) => p.category))];

const allVersions = [...new Set(products.flatMap((p) => p.versions))].sort((a, b) => parseFloat(a) - parseFloat(b));

export const catalogueStats = {
  total: products.length,
  apps: products.filter((p) => p.kind === 'app').length,
  themes: products.filter((p) => p.kind === 'theme').length,
  oldestVersion: allVersions[0],
  newestVersion: allVersions[allVersions.length - 1],
};

/** Store page for one specific Odoo series of a product. */
export function storeUrlForVersion(product: Product, version: string): string {
  return product.storeUrl.replace(/\/\d+\.\d+\/([^/]+)$/, `/${version}/$1`);
}

/** Up to `count` other products in the same category, starting after this one. */
export function relatedProducts(product: Product, count = 3): Product[] {
  const peers = products.filter((p) => p.category === product.category);
  const start = peers.indexOf(product);
  return [...peers.slice(start + 1), ...peers.slice(0, start)].slice(0, count);
}
